package com.lifemax.rpg.feature.habits

import com.lifemax.rpg.feature.habits.domain.Ambient
import com.lifemax.rpg.feature.habits.presentation.scene.AirSprite
import com.lifemax.rpg.feature.habits.presentation.scene.AirSprites
import com.lifemax.rpg.feature.habits.presentation.scene.BirdShape
import kotlin.math.abs
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The painted things of the air (the airliner, its contrail, the blimp) are generated by pure
 * Kotlin: the same pixels every time, white at every alpha so the hour can tint them, their light
 * never more than their body, nothing touching the picture's border, the whole lot inside its
 * memory budget. The birds' helpers stay in range and move smoothly.
 */
class AirSpritesTest {
    private val plane: AirSprite by lazy { AirSprites.plane() }
    private val trail: AirSprite by lazy { AirSprites.contrail() }
    private val blimp: AirSprite by lazy { AirSprites.blimp() }

    private fun alpha(c: Int) = c ushr 24

    @Test
    fun theSpritesAreTheSameEveryTime() {
        val again = listOf(AirSprites.plane(), AirSprites.contrail(), AirSprites.blimp())
        for ((i, s) in listOf(plane, trail, blimp).withIndex()) {
            assertEquals(s.layers.size, again[i].layers.size)
            for (l in s.layers.indices) assertArrayEquals(s.layers[l], again[i].layers[l])
        }
    }

    @Test
    fun theSpritesAreWhiteTintableLayersOfTheirStatedSize() {
        assertEquals(AirSprites.LAYERS, plane.layers.size)
        assertEquals(AirSprites.BLIMP_LAYERS, blimp.layers.size)
        assertEquals(AirSprites.TRAIL_LAYERS, trail.layers.size)
        assertEquals(AirSprites.PLANE_W * AirSprites.PLANE_H, plane.layers[0].size)
        assertEquals(AirSprites.BLIMP_W * AirSprites.BLIMP_H, blimp.layers[0].size)
        assertEquals(AirSprites.TRAIL_W * AirSprites.TRAIL_H, trail.layers[0].size)
        for (s in listOf(plane, trail, blimp)) {
            for (layer in s.layers) {
                assertEquals(s.w * s.h, layer.size)
                assertTrue(layer.all { alpha(it) == 0 || (it and 0xFFFFFF) == 0xFFFFFF })
            }
            // the light is a part of the body, never more than it
            for (l in 1 until s.layers.size) for (p in s.layers[0].indices) assertTrue(
                alpha(s.layers[l][p]) <= alpha(s.layers[0][p]) + 1
            )
            // something solid, something lit
            assertTrue(s.layers[0].any { alpha(it) > 240 })
            assertTrue(s.layers[1].any { alpha(it) > 60 })
        }
    }

    @Test
    fun nothingTouchesTheBorder() {
        for (s in listOf(plane, trail, blimp)) for (layer in s.layers) {
            for (x in 0 until s.w) {
                assertEquals(0, alpha(layer[x]))
                assertEquals(0, alpha(layer[(s.h - 1) * s.w + x]))
            }
            for (y in 0 until s.h) {
                assertEquals(0, alpha(layer[y * s.w]))
                assertEquals(0, alpha(layer[y * s.w + s.w - 1]))
            }
        }
    }

    @Test
    fun thePlaneIsLitFromTheUpperLeftWithWindowsAlongItsSide() {
        // in profile: the back of the hull and the fin (above the centre line) catch more light
        // than the belly, the near wing and the engines under it
        fun litMean(y0: Int, y1: Int): Float {
            var sum = 0f
            var n = 0
            for (y in y0 until y1) for (x in 0 until plane.w) {
                val i = y * plane.w + x
                if (alpha(plane.layers[AirSprites.SHADE][i]) > 200) {
                    sum += alpha(plane.layers[AirSprites.LIT][i])
                    n++
                }
            }
            return if (n == 0) 0f else sum / n
        }
        val oy = plane.oy.toInt()
        assertTrue(litMean(0, oy) > litMean(oy, plane.h) * 1.2f)
        // the gleam is a thin line: bright somewhere, but a small share of the body
        val glint = plane.layers[AirSprites.GLINT]
        assertTrue(glint.any { alpha(it) > 150 })
        assertTrue(glint.count { alpha(it) > 100 } * 8 < plane.layers[0].count { alpha(it) > 200 })
        // the windows: a row of small lit spots, several of them, each a few pixels
        val win = plane.layers[AirSprites.GLOW]
        val lit = win.count { alpha(it) > 120 }
        assertTrue("window pixels $lit", lit in 12..400)
        // the fin rises well above the hull, the near wing and engines hang below it
        val shade = plane.layers[AirSprites.SHADE]
        fun solidRows(y0: Int, y1: Int) =
            (y0 until y1).count { y ->
                (0 until plane.w).any { alpha(shade[y * plane.w + it]) > 200 }
            }
        assertTrue(solidRows(0, oy - (2f * plane.ppd).toInt()) > (3f * plane.ppd).toInt())
        assertTrue(solidRows(oy + (1.5f * plane.ppd).toInt(), plane.h) > (2f * plane.ppd).toInt())
        // and it is long and thin: far wider than it is tall
        val cols =
            (0 until plane.w).count { x ->
                (0 until plane.h).any { alpha(shade[it * plane.w + x]) > 200 }
            }
        val rows = solidRows(0, plane.h)
        assertTrue("$cols x $rows", cols > rows * 2)
        // the belly bounce lies low: more of it below the centre line than above
        val bounce = plane.layers[AirSprites.BOUNCE]
        var above = 0L
        var below = 0L
        for (y in 0 until plane.h) for (x in 0 until plane.w) {
            val a = alpha(bounce[y * plane.w + x]).toLong()
            if (y < oy) above += a else below += a
        }
        assertTrue(below > above)
    }

    @Test
    fun theContrailStartsAsTwoCoresAndThinsToNothing() {
        val body = trail.layers[AirSprites.TRAIL_BODY]
        val core = trail.layers[AirSprites.TRAIL_CORE]
        fun column(layer: IntArray, dp: Float): IntArray {
            val x = (trail.ox - (dp + AirSprites.TRAIL_GAP) * trail.ppd).toInt()
            return IntArray(trail.h) { alpha(layer[it * trail.w + x]) }
        }
        // right behind the engines (nearly in line, seen from the street): two peaks, one above
        // and one below the centre line, a dip between; a few dp on they have merged into one
        val near = column(body, 2.5f)
        val mid = trail.h / 2
        val upper = near.slice(0 until mid).max()
        val lower = near.slice(mid until trail.h).max()
        assertTrue("cores $upper $lower", upper > 100 && lower > 100)
        assertTrue(
            "dip ${near[mid]} between $upper and $lower",
            near[mid] < minOf(upper, lower) * .75f,
        )
        val merged = column(body, 20f)
        val mergedSides =
            maxOf(merged.slice(0 until mid).max(), merged.slice(mid until trail.h).max())
        assertTrue(merged[mid] >= mergedSides * .9f)
        // far back there is one soft body wider than the cores were, and fainter
        val far = column(body, 150f)
        val nearBody = column(body, 8f)
        assertTrue(far.count { it > 20 } > nearBody.count { it > 20 })
        assertTrue(far.max() < nearBody.max())
        // and by the end, nothing
        assertTrue(column(body, AirSprites.TRAIL_DP - AirSprites.TRAIL_GAP - 1f).all { it < 8 })
        // and nothing between the engines and the gap past the tail: it doesn't start under the
        // plane
        for (k in 0 until (AirSprites.TRAIL_GAP * trail.ppd).toInt()) assertTrue(
            (0 until trail.h).all { alpha(body[it * trail.w + (trail.ox - k).toInt()]) < 4 }
        )
        // the core is never more than the body
        for (p in body.indices) assertTrue(alpha(core[p]) <= alpha(body[p]) + 1)
    }

    @Test
    fun theBlimpHasALitPanelAndGondolaWindows() {
        val glow = blimp.layers[AirSprites.GLOW]
        // the panel: a wide run of glow on the envelope's side, inside the band's bounds
        val x0 = (blimp.ox + AirSprites.BAND_L * blimp.ppd).toInt()
        val x1 = (blimp.ox + AirSprites.BAND_R * blimp.ppd).toInt()
        val y = (blimp.oy + (AirSprites.BAND_T + AirSprites.BAND_B) / 2f * blimp.ppd + 3f).toInt()
        var lit = 0
        for (x in x0 until x1) if (alpha(glow[y * blimp.w + x]) > 100) lit++
        assertTrue("panel pixels $lit of ${x1 - x0}", lit > (x1 - x0) * 3 / 4)
        // nothing glows above the panel's top
        val above = (blimp.oy + (AirSprites.BAND_T - 1f) * blimp.ppd).toInt()
        for (yy in 0 until above) for (x in 0 until blimp.w) assertEquals(
            0,
            alpha(glow[yy * blimp.w + x]),
        )
        // the cabin's windows glow under the envelope, a row of panes
        val gy = (blimp.oy + AirSprites.WINDOW_Y * blimp.ppd).toInt()
        val panes = (0 until blimp.w).count { alpha(glow[gy * blimp.w + it]) > 100 }
        assertTrue("window pixels $panes", panes > 10)
        // the top of the envelope is lit more than its belly
        fun litAt(dp: Float): Int {
            val yy = (blimp.oy + dp * blimp.ppd).toInt()
            return alpha(blimp.layers[AirSprites.LIT][yy * blimp.w + blimp.ox.toInt()])
        }
        assertTrue(litAt(-4f) > litAt(4f) + 80)
    }

    @Test
    fun theBlimpIsAnAirshipWithFinsInACrossAndItsLivery() {
        val shade = blimp.layers[AirSprites.SHADE]
        fun solid(xDp: Float, yDp: Float): Boolean {
            val x = (blimp.ox + xDp * blimp.ppd).toInt()
            val y = (blimp.oy + yDp * blimp.ppd).toInt()
            return alpha(shade[y * blimp.w + x]) > 200
        }
        // a hull far longer than it is deep, fullest towards its nose
        assertTrue(solid(AirSprites.HULL_HALF - 1.5f, 0f) && solid(-AirSprites.HULL_HALF + 4f, 0f))
        assertTrue(!solid(0f, -AirSprites.HULL_R - .8f) && solid(0f, -AirSprites.HULL_R + .8f))
        assertTrue(AirSprites.envelopeR(8f) > AirSprites.envelopeR(-8f))
        // the upper and lower fins stand well clear of the tail, the cabin hangs under the front
        assertTrue(solid(-22f, -9f) && solid(-22f, 8.5f))
        assertTrue(solid(8f, AirSprites.HULL_R + 2f) && !solid(-8f, AirSprites.HULL_R + 2f))
        // the livery: a share of the body painted, never more than the body (checked above), and
        // the panel's middle mostly paint
        val paint = blimp.layers[AirSprites.LIVERY]
        val painted = paint.count { alpha(it) > 120 }
        val body = shade.count { alpha(it) > 200 }
        assertTrue("painted $painted of $body", painted in body / 30..body / 4)
        // the gleam is a highlight: bright somewhere, a small share of the body
        val glint = blimp.layers[AirSprites.GLINT]
        assertTrue(glint.any { alpha(it) > 90 })
        assertTrue(glint.count { alpha(it) > 60 } * 6 < body)
        // the draw order holds each layer once
        assertEquals(AirSprites.BLIMP_LAYERS, AirSprites.BLIMP_ORDER.toSet().size)
    }

    @Test
    fun theWholeLotFitsItsBudget() {
        val bytes = AirSprites.bytes()
        assertEquals(plane.bytes + trail.bytes + blimp.bytes, bytes)
        assertTrue("air sprites are $bytes bytes", bytes < 1600 * 1024)
    }

    @Test
    fun theBirdsHelpersStayInRangeAndMoveSmoothly() {
        for (i in 0 until Ambient.FLOCK) {
            assertTrue(Ambient.birdTier(i) in 0..2)
            assertTrue(Ambient.birdSize(i) in .5f..1f)
            assertTrue(Ambient.birdFade(i) in .5f..1f)
            assertTrue(Ambient.birdRate(i) in 5f..9f)
            var last = Ambient.flap(i, 0f)
            var glided = false
            var t = 0f
            while (t < 120f) {
                t += 1f / 60f
                val f = Ambient.flap(i, t)
                assertTrue(f in -1f..1f)
                // no jump between frames: a beat at nine radians a second moves under .2 a frame
                assertTrue("bird $i jumped ${abs(f - last)} at $t", abs(f - last) < .2f)
                last = f
                val g = Ambient.glide(i, t)
                assertTrue(g in 0f..1f)
                if (g > .99f) glided = true
                assertTrue(abs(Ambient.birdBob(i, t)) < 1.1f)
            }
            assertTrue("bird $i never glides", glided)
        }
        // the sizes differ: a near bird, a far one
        assertTrue((0 until Ambient.FLOCK).map { Ambient.birdTier(it) }.toSet().size == 3)
        // the far ones beat slower
        assertTrue(Ambient.birdRate(3) < Ambient.birdRate(0))
    }

    @Test
    fun theBirdShapeIsAClosedBodyAndTwoWingsThatFitTheArray() {
        val out = FloatArray(BirdShape.CAPACITY)
        for (flap in listOf(-1f, -.5f, 0f, .5f, 1f)) for (dir in listOf(-1f, 1f)) {
            val n = BirdShape.build(10f, 20f, flap, 1f, dir, out)
            assertTrue(n <= BirdShape.CAPACITY)
            // three closed shapes, each starting with a move
            var closes = 0
            var moves = 0
            var k = 0
            var minX = Float.MAX_VALUE
            var maxX = -Float.MAX_VALUE
            var minY = Float.MAX_VALUE
            var maxY = -Float.MAX_VALUE
            while (k < n) {
                val step =
                    when (out[k]) {
                        BirdShape.MOVE -> {
                            moves++
                            3
                        }
                        BirdShape.LINE -> 3
                        BirdShape.CUBIC -> 7
                        else -> {
                            closes++
                            1
                        }
                    }
                var j = k + 1
                while (j < k + step) {
                    minX = minOf(minX, out[j])
                    maxX = maxOf(maxX, out[j])
                    minY = minOf(minY, out[j + 1])
                    maxY = maxOf(maxY, out[j + 1])
                    j += 2
                }
                k += step
            }
            assertEquals(3, moves)
            assertEquals(3, closes)
            // it spans its wings about the centre and stays within a few dp of it
            assertTrue(maxX - 10f > BirdShape.SPAN - 1.5f && 10f - minX > BirdShape.SPAN - 1.5f)
            assertTrue(minY > 20f - 7f && maxY < 20f + 7f)
        }
        // the wings move: up and down are different pictures
        val up = FloatArray(BirdShape.CAPACITY)
        val down = FloatArray(BirdShape.CAPACITY)
        BirdShape.build(0f, 0f, 1f, 1f, 1f, up)
        BirdShape.build(0f, 0f, -1f, 1f, 1f, down)
        assertFalse(up.contentEquals(down))
    }
}
